structure.schema.prisma:
// This is your Prisma schema file

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model Usuario {
  id       String   @id @default(uuid())
  email    String   @unique
  nombre   String
  apellido String
  activo   Boolean  @default(true)

  // Relaciones
  posts    Post[]
  perfil   Perfil?

  // Relaciones inversas
  // Comentarios en posts de otros usuarios
  comentarios Comentario[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([email])
  @@index([activo])
  @@map("usuarios")
}

model Post {
  id        String   @id @default(uuid())
  titulo    String
  contenido String   @db.Text
  publicado Boolean  @default(false)

  // Relaciones
  autorId   String
  autor     Usuario  @relation(fields: [autorId], references: [id], onDelete: Cascade)

  // Relaciones inversas
  comentarios Comentario[]
  categorias  CategoriaEnPost[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([autorId])
  @@index([publicado])
  @@map("posts")
}

model Perfil {
  id        String  @id @default(uuid())
  bio       String? @db.Text
  avatar    String?
  telefono  String?

  // Relaciones
  usuarioId String  @unique
  usuario   Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)

  // Relaciones inversas
  // (ninguna en este caso)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([usuarioId])
  @@map("perfiles")
}

model Comentario {
  id        String   @id @default(uuid())
  contenido String   @db.Text

  // Relaciones
  postId    String
  post      Post     @relation(fields: [postId], references: [id], onDelete: Cascade)

  autorId   String
  autor     Usuario  @relation(fields: [autorId], references: [id], onDelete: Cascade)

  // Relaciones inversas
  // (ninguna en este caso)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([postId])
  @@index([autorId])
  @@map("comentarios")
}

model Categoria {
  id     String @id @default(uuid())
  nombre String @unique
  slug   String @unique

  // Relaciones
  // (ninguna directa)

  // Relaciones inversas
  posts CategoriaEnPost[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([slug])
  @@map("categorias")
}

model CategoriaEnPost {
  // Relaciones
  postId      String
  post        Post      @relation(fields: [postId], references: [id], onDelete: Cascade)

  categoriaId String
  categoria   Categoria @relation(fields: [categoriaId], references: [id], onDelete: Cascade)

  // Relaciones inversas
  // (ninguna en este caso)

  asignadoEn DateTime @default(now())

  @@id([postId, categoriaId])
  @@index([postId])
  @@index([categoriaId])
  @@map("categorias_en_posts")
}
